use bhoo::*;
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_search_view.rs"));}
const B:Rect=Rect{x:0.,y:0.,width:350.,height:48.};
fn draw(ui:&mut Ui,s:&mut android_xml::LayoutState,input:Input)->Option<&'static str>{let mut action=None;ui.frame(input,B,0.,|f|action=fixture::LAYOUT.render(f,B,s));action}
fn click(ui:&mut Ui,s:&mut android_xml::LayoutState,label:&str,time:f64)->Option<&'static str>{let b=ui.semantics().iter().find(|n|n.label.as_ref()==label).unwrap().bounds;let p=Some([b.x+b.width/2.,b.y+b.height/2.]);draw(ui,s,Input{pointer:p,pressed:true,time,..Input::default()});draw(ui,s,Input{pointer:p,released:true,time:time+0.01,..Input::default()})}
#[test] fn expand_clear_and_collapse(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();draw(&mut ui,&mut s,Input::default());assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Open search"));click(&mut ui,&mut s,"Open search",1.);assert!(s.take_search_focus_request("search"));assert!(!s.take_search_focus_request("search"));draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Search locally"));s.set_search_query("search","hello");assert_eq!(draw(&mut ui,&mut s,Input{time:1.2,..Input::default()}),Some("search"));assert_eq!(click(&mut ui,&mut s,"Clear search",1.3),Some("search"));assert_eq!(s.text["search"],"");assert!(s.take_search_focus_request("search"));draw(&mut ui,&mut s,Input{time:1.4,..Input::default()});click(&mut ui,&mut s,"Close search",1.5);assert!(!s.search_open["search"]);}
#[test] fn submit_requires_nonblank_and_reports_original_query(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();draw(&mut ui,&mut s,Input::default());s.set_search_query("search","   ");assert!(!s.submit_search("search"));s.set_search_query("search","  cats  ");assert!(s.submit_search("search"));assert_eq!(s.search_submitted["search"],"  cats  ");assert_eq!(draw(&mut ui,&mut s,Input{time:1.,..Input::default()}),Some("search"));}
#[test] fn always_expanded_view_hides_close_until_query_exists(){use bhoo::android_xml::RelativeRule;static RULES:[RelativeRule;1]=[RelativeRule{kind:106,anchor:"false"}];let mut node=fixture::LAYOUT.children[0];node.relative_rules=&RULES;let node=Box::leak(Box::new(node));let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();ui.frame(Input::default(),B,0.,|f|{node.render(f,B,&mut s);});assert!(s.search_open["search"]);assert!(!ui.semantics().iter().any(|n|n.label.as_ref()=="Close search"));s.set_search_query("search","x");ui.frame(Input::default(),B,0.,|f|{node.render(f,B,&mut s);});assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Clear search"));}
#[test] fn local_suggestion_activation_reports_index_without_rewriting_query(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.set_autocomplete_items("search",["Calendar","Camera","Cats"].map(str::to_owned).to_vec());let view=Rect{x:0.,y:0.,width:350.,height:400.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut a=None;ui.frame(input,view,0.,|f|a=fixture::LAYOUT.render(f,B,s));a};draw(&mut ui,&mut s,Input::default());let p=Some([24.,24.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.,..Input::default()});draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.01,..Input::default()});draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});ui.adapter_focus(Some(android_xml::view_id("search")));s.set_search_query("search","ca");draw(&mut ui,&mut s,Input{time:1.2,..Input::default()});let rect=ui.semantics().iter().find(|n|n.label.as_ref()=="Camera").unwrap().bounds;let p=Some([rect.x+10.,rect.y+10.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.3,..Input::default()});assert_eq!(draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.31,..Input::default()}),Some("search"));assert_eq!(s.search_suggestion_clicked["search"],1);assert_eq!(s.text["search"],"ca");assert!(!s.search_submitted.contains_key("search"));}
#[test] fn enter_activates_highlighted_suggestion_without_submitting_query() {
    let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.set_autocomplete_items("search",["Calendar","Camera"].map(str::to_owned).to_vec());
    let view=Rect{x:0.,y:0.,width:350.,height:400.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut action=None;ui.frame(input,view,0.,|f|action=fixture::LAYOUT.render(f,B,s));action};
    s.search_open.insert("search".into(),true);draw(&mut ui,&mut s,Input::default());ui.adapter_focus(Some(android_xml::view_id("search")));s.set_search_query("search","ca");draw(&mut ui,&mut s,Input{time:0.1,..Input::default()});
    let key=|key,time|Input{time,key:Some(KeyInput{key,pressed:true,repeat:false,shift:false}),..Input::default()};
    draw(&mut ui,&mut s,key(Key::Down,0.2));assert_eq!(s.text["search"],"Calendar");
    draw(&mut ui,&mut s,key(Key::Down,0.3));assert_eq!(s.text["search"],"Camera");
    assert_eq!(draw(&mut ui,&mut s,key(Key::Enter,0.4)),Some("search"));
    assert_eq!(s.search_suggestion_clicked["search"],1);assert!(!s.search_submitted.contains_key("search"));
    draw(&mut ui,&mut s,Input{time:0.5,..Input::default()});assert!(!s.autocomplete_is_open("search"));
    s.set_search_query("search","other");draw(&mut ui,&mut s,Input{time:0.6,..Input::default()});draw(&mut ui,&mut s,key(Key::Enter,0.7));assert_eq!(s.search_submitted["search"],"other");
}
#[test] fn suggestion_popup_wraps_results_and_fits_the_viewport() {
    let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();
    s.search_open.insert("search".into(),true);s.set_autocomplete_items("search",["Calendar","Camera"].map(str::to_owned).to_vec());
    let view=Rect{x:0.,y:0.,width:350.,height:400.};ui.frame(Input::default(),view,0.,|f|{fixture::LAYOUT.render(f,B,&mut s);});ui.adapter_focus(Some(android_xml::view_id("search")));s.set_search_query("search","ca");
    let commands=ui.frame(Input{time:0.1,..Input::default()},view,0.,|f|{fixture::LAYOUT.render(f,B,&mut s);});
    assert!(commands.iter().any(|c|matches!(c,DrawCommand::RoundedRect{bounds,radius,..} if *radius==4.0 && bounds.y==48.0 && bounds.height==96.0)));
    s.set_autocomplete_items("search",(0..30).map(|i|format!("Camera {i}")).collect());
    let commands=ui.frame(Input{time:0.2,..Input::default()},view,0.,|f|{fixture::LAYOUT.render(f,B,&mut s);});
    assert!(commands.iter().any(|c|matches!(c,DrawCommand::RoundedRect{bounds,radius,..} if *radius==4.0 && bounds.y==48.0 && bounds.height==352.0)));
}
#[test] fn uses_platform_icons_and_focus_underline(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();let commands=ui.frame(Input::default(),B,0.,|f|{fixture::LAYOUT.render(f,B,&mut s);});let has=|items:&[DrawCommand],name:&str|items.iter().any(|c|matches!(c,DrawCommand::Shape{index,..} if shape_data(*index as usize).is_some_and(|shape|shape.name==name)));assert!(has(&commands,"ic_search_api_material"));click(&mut ui,&mut s,"Open search",1.);draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});ui.adapter_focus(Some(android_xml::view_id("search")));s.search_submit_enabled.insert("search".into());s.set_search_query("search","owl");let commands=ui.frame(Input{time:1.2,..Input::default()},B,0.,|f|{fixture::LAYOUT.render(f,B,&mut s);});assert!(has(&commands,"ic_clear_material"));assert!(has(&commands,"ic_go_search_api_material"));assert!(commands.iter().any(|c|matches!(c,DrawCommand::Line{width,..} if *width==2.0)));}
